import{_ as a,a0 as r,w as o,s as f,ao as s,I as n,x as e,a1 as p,A as u}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const c=JSON.parse('{"title":"Ubuntu每日小技巧：通過PPA升級你的LibreOffice | LCTT x X-CMD","titleTemplate":false,"description":"Ubuntu每日小技巧：通過PPA升級你的LibreOffice | LCTT (201311) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Ubuntu每日小技巧：通過PPA升級你的LibreOffice | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Ubuntu每日小技巧：通過PPA升級你的LibreOffice | LCTT (201311) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201311/Daily Ubuntu Tips–Update To LibreOffice Latest In Ubuntu Via PPA","title":"Ubuntu每日小技巧：通過PPA升級你的LibreOffice","tag":"201311","desc":""},"relativePath":"201311/Daily Ubuntu Tips–Update To LibreOffice Latest In Ubuntu Via PPA.md","filePath":"[post].md"}'),b={name:"201311/Daily Ubuntu Tips–Update To LibreOffice Latest In Ubuntu Via PPA.md"};function l(d,t,L,T,P,m){const i=r("Link");return o(),f("div",null,[t[11]||(t[11]=s(`<h1 id="ubuntu每日小技巧-通過ppa升級你的libreoffice" tabindex="-1">Ubuntu每日小技巧：通過PPA升級你的LibreOffice <a class="header-anchor" href="#ubuntu每日小技巧-通過ppa升級你的libreoffice" aria-label="Permalink to “Ubuntu每日小技巧：通過PPA升級你的LibreOffice”">​</a></h1><p>對於每一個你新安裝的Ubuntu系統，你都會擁有一個可以讓你辦公的辦公工具——LibreOffice。很多人都知道微軟公司的的Word、Excel、PowerPoint和Outlook，但是很少有人知道LibreOffice。</p><p>LibreOffice靠來自全世界的志願者來維護，由一個慈善基金會支持。它是Linux社區的一款主要的免費辦公工具。它可以安裝在Windows，Mac OS X和Linux等系統的計算機上。</p><p>就在5天前（譯註：好吧，這個翻譯稿拖了5天了~~，原文為“今天”。），一個新的版本將面向公眾開放了。Windows，Mac OS X和Linux用户可以直接從下載頁面下載最新版本了。</p><p>Ubuntu用户擁有添加LibreOffice軟件倉庫到自己的電腦來安裝升級最新版的優勢。如果你想要在最新版本可用時最快的得到它，這種方法將會很有用。</p><p>最新的LibreOffice套裝版本是4.1。每一個後續的版本可以立即在4.1的倉庫中找到，直到新的主線版本比如4.2的推出。</p><p>所以，為了在Ubuntu中自動的升級，請添加下面的軟件倉庫地址。</p><pre><code>sudo add-apt-repository ppa:libreoffice/ppa
</code></pre><p>接着，運行如下命令來升級最新的LibreOffice。</p><pre><code>sudo apt-get update &amp;&amp; sudo apt-get dist-upgrade
</code></pre><p>這樣就好了。當你添加上面的倉庫然後升級系統，Ubuntu將會自動的下載安裝最新的LibreOffice版本。</p><p>Windows和Mac OS X用户可以直接在程序套件中升級或者直接從網頁中下載。</p><p><img src="http://www.liberiangeek.net/wp-content/uploads/2013/11/libreoffice-upgrade-ubuntu.png" alt=""></p><p>Enjoy!</p><hr>`,15)),n("p",null,[t[1]||(t[1]=e("via: ",-1)),p(i,{href:"http://www.liberiangeek.net/2013/11/daily-ubuntu-tipsupdate-to-libreoffice-latest-in-ubuntu-via-ppa/"},{default:u(()=>[...t[0]||(t[0]=[e("http://www.liberiangeek.net/2013/11/daily-ubuntu-tipsupdate-to-libreoffice-latest-in-ubuntu-via-ppa/",-1)])]),_:1})]),n("p",null,[t[4]||(t[4]=e("譯者：",-1)),p(i,{href:"https://github.com/scusjs"},{default:u(()=>[...t[2]||(t[2]=[e("SCUSJS",-1)])]),_:1}),t[5]||(t[5]=e(" 校對：",-1)),p(i,{href:"https://github.com/wxy"},{default:u(()=>[...t[3]||(t[3]=[e("wxy",-1)])]),_:1})]),n("p",null,[t[8]||(t[8]=e("本文由 ",-1)),p(i,{href:"https://github.com/LCTT/TranslateProject"},{default:u(()=>[...t[6]||(t[6]=[e("LCTT",-1)])]),_:1}),t[9]||(t[9]=e(" 原創翻譯，",-1)),p(i,{href:"http://linux.cn/"},{default:u(()=>[...t[7]||(t[7]=[e("Linux中國",-1)])]),_:1}),t[10]||(t[10]=e(" 榮譽推出",-1))])])}const w=a(b,[["render",l]]);export{c as __pageData,w as default};
